param([Parameter(Mandatory=$true)][string]$ReleaseDirectory,[Parameter(Mandatory=$true)][ValidatePattern('\A\d+\.\d+\.\d+\z')][string]$Version,[Parameter(Mandatory=$true)][ValidatePattern('\A[a-f0-9]{40}\z')][string]$SourceCommit,[Parameter(Mandatory=$true)][ValidateNotNullOrEmpty()][string]$ExpectedSubject,[switch]$VerifyOnly,[switch]$ValidateUnsigned)
$ErrorActionPreference='Stop'
if([string]::IsNullOrWhiteSpace($ExpectedSubject)){throw 'An exact verified publisher Subject is required.'}
Import-Module -Name ([IO.Path]::Combine($PSHOME,'Modules','Microsoft.PowerShell.Utility','Microsoft.PowerShell.Utility.psd1')) -ErrorAction Stop
Import-Module -Name ([IO.Path]::Combine($PSHOME,'Modules','Microsoft.PowerShell.Security','Microsoft.PowerShell.Security.psd1')) -ErrorAction Stop
function Assert-RelayReleaseIdentity($Value,[string]$ExpectedVersion,[string]$ExpectedCommit,[bool]$ReadOnly){
 if($Value.release -cne $ExpectedVersion -or $Value.sourceRepository -cne 'https://github.com/GiovanniVarg/Relay' -or $Value.sourceCommit -cne $ExpectedCommit -or $Value.status -cne 'beta-testing' -or $Value.credentialsIncluded -isnot [bool] -or $Value.credentialsIncluded -ne $false -or $Value.unsigned -isnot [bool] -or $Value.unsigned -ne (-not $ReadOnly) -or $Value.payload.schema -ne 1 -or $Value.payload.name -cne 'relay-agent-harness' -or $Value.payload.version -cne $ExpectedVersion -or $Value.payload.developmentFixture -isnot [bool] -or $Value.payload.developmentFixture -ne $false){throw 'Release identity, credential boundary or signing transition is invalid.'}
}
function Assert-RelayNoLinks([string]$Path){$cursor=[IO.Path]::GetFullPath($Path);while($cursor){if(([IO.File]::GetAttributes($cursor) -band [IO.FileAttributes]::ReparsePoint) -ne 0){throw 'Linked release inputs are refused.'};$parent=[IO.Path]::GetDirectoryName($cursor);if($parent -eq $cursor){break};$cursor=$parent}}
function Hash-RelayFile([string]$Path){$stream=[IO.File]::OpenRead($Path);$hash=[Security.Cryptography.SHA256]::Create();try{return [BitConverter]::ToString($hash.ComputeHash($stream)).Replace('-','').ToLowerInvariant()}finally{$hash.Dispose();$stream.Dispose()}}
function Read-RelayJson([string]$Path){$file=[IO.FileInfo]::new($Path);if($file.Length -gt 8MB){throw 'Release metadata exceeds bounds.'};return ([IO.File]::ReadAllText($Path)|ConvertFrom-Json)}
if($VerifyOnly -and $ValidateUnsigned){throw 'Choose either unsigned preflight or signed verification.'}
$ReleaseDirectory=[IO.Path]::GetFullPath($ReleaseDirectory);Assert-RelayNoLinks $ReleaseDirectory
$name='Relay-Setup-'+$Version+'-beta-windows-x64.exe';$payloadNames=@($name,'components.json','THIRD_PARTY_NOTICES.txt');$names=@($payloadNames)+@('SHA256SUMS.txt')
$files=@([IO.Directory]::EnumerateFiles($ReleaseDirectory));if($files.Count -ne 4){throw 'Release directory must contain exactly four known files.'};foreach($file in $files){if([IO.Path]::GetFileName($file) -cnotin $names){throw 'Unknown release asset.'};Assert-RelayNoLinks $file;$asset=[IO.FileInfo]::new($file);$limit=switch -CaseSensitive ([IO.Path]::GetFileName($file)){$name {128MB};'components.json' {8MB};'THIRD_PARTY_NOTICES.txt' {12MB};'SHA256SUMS.txt' {4096}};if($asset.Length -lt 1 -or $asset.Length -gt $limit){throw 'Release asset size exceeds its production bound.'}}
$original=@{};foreach($file in $names){$original[$file]=Hash-RelayFile ([IO.Path]::Combine($ReleaseDirectory,$file))}
$components=Read-RelayJson ([IO.Path]::Combine($ReleaseDirectory,'components.json'));Assert-RelayReleaseIdentity $components $Version $SourceCommit ([bool]$VerifyOnly)
# Finalization accepts the original unsigned checksum manifest only as an input identity witness.
# The installer line changes during signing; the two unchanged metadata/notices lines must still match.
$seen=@{};foreach($line in [IO.File]::ReadAllLines([IO.Path]::Combine($ReleaseDirectory,'SHA256SUMS.txt'))){if($line -cnotmatch '^([a-f0-9]{64})  ([^\r\n]+)$'){throw 'Malformed release checksum.'};$hash=$Matches[1];$file=$Matches[2];if($file -cnotin $payloadNames -or $seen.ContainsKey($file)){throw 'Unknown or duplicate checksum asset.'};if(($VerifyOnly -or $ValidateUnsigned -or $file -cne $name) -and $hash -cne $original[$file]){throw 'Release checksum mismatch.'};$seen[$file]=$true};if($seen.Count -ne 3){throw 'Missing release checksum.'}
$exe=[IO.Path]::Combine($ReleaseDirectory,$name);$pe=[Diagnostics.FileVersionInfo]::GetVersionInfo($exe);if($pe.ProductName -cne 'Relay' -or $pe.FileVersion -cne ($Version+'.0') -or $pe.ProductVersion -cne ($Version+'-beta')){throw 'Installer PE identity does not match this production version.'}
if($ValidateUnsigned){if((Get-AuthenticodeSignature -LiteralPath $exe).Status.ToString() -cne 'NotSigned'){throw 'Unsigned signing input already has a signature or invalid signature state.'};if($components.PSObject.Properties.Name -contains 'signing'){throw 'Unsigned input carries signing claims.'};[ordered]@{verified=$true;readOnly=$true;version=$Version;sourceCommit=$SourceCommit;artifactSha256=$original[$name];signed=$false}|ConvertTo-Json -Compress;return}
$exe=[IO.Path]::Combine($ReleaseDirectory,$name);$verification=& ([IO.Path]::Combine($PSScriptRoot,'verify-authenticode.ps1')) -LiteralPath $exe -ExpectedSubject $ExpectedSubject
$signing=$verification|ConvertFrom-Json;if($signing.verified -ne $true -or $signing.subject -cne $ExpectedSubject -or $signing.artifactSha256 -cne $original[$name]){throw 'Native signing verification did not bind the exact installer.'}
foreach($file in $names){if((Hash-RelayFile ([IO.Path]::Combine($ReleaseDirectory,$file))) -cne $original[$file]){throw 'Release bytes changed during verification.'}}
if($VerifyOnly){
 $expectedFields=@('schema','verified','artifactSha256','subject','issuer','signerCertificateSha256','timestampSubject','timestampCertificateSha256','verification','timestampRequired','fileDigest');if(-not $components.signing -or @($components.signing.PSObject.Properties).Count -ne $expectedFields.Count){throw 'Incomplete signed component metadata.'};foreach($field in $expectedFields){if($components.signing.$field -cne $signing.$field){throw 'Signed component metadata differs from actual native evidence.'}}
}else{
 if($components.PSObject.Properties.Name -contains 'signing'){throw 'The unsigned release already carries signing metadata; inspect before retrying.'}
 $components.unsigned=$false;$components|Add-Member -MemberType NoteProperty -Name signing -Value $signing
 $componentBytes=[Text.UTF8Encoding]::new($false).GetBytes(($components|ConvertTo-Json -Depth 20));$componentPath=[IO.Path]::Combine($ReleaseDirectory,'components.json')
 # Each replacement is atomic; partial/unknown finalization is never silently replayed.
 $temp=$componentPath+'.finalize-'+[Guid]::NewGuid().ToString('N');$stream=[IO.File]::Open($temp,[IO.FileMode]::CreateNew);try{$stream.Write($componentBytes,0,$componentBytes.Length);$stream.Flush($true)}finally{$stream.Dispose()};[IO.File]::Replace($temp,$componentPath,$null)
 $lines=@();foreach($file in $payloadNames){$lines+=((Hash-RelayFile ([IO.Path]::Combine($ReleaseDirectory,$file)))+'  '+$file)}
 $sumPath=[IO.Path]::Combine($ReleaseDirectory,'SHA256SUMS.txt');$temp=$sumPath+'.finalize-'+[Guid]::NewGuid().ToString('N');$bytes=[Text.UTF8Encoding]::new($false).GetBytes(($lines -join "`n")+"`n");$stream=[IO.File]::Open($temp,[IO.FileMode]::CreateNew);try{$stream.Write($bytes,0,$bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()};[IO.File]::Replace($temp,$sumPath,$null)
}
[ordered]@{verified=$true;readOnly=[bool]$VerifyOnly;version=$Version;sourceCommit=$SourceCommit;artifactSha256=$signing.artifactSha256;subject=$ExpectedSubject;signed=$true}|ConvertTo-Json -Compress
